const today = new Date();

return $input.all().map(item => {
  const buyingGroup = item.json.buyingGroup || [];

  // Process each member in the buying group
  const processedGroup = buyingGroup.map(member => {
    const signals = member.signals || [];
    const negativeSignals = member.negativeSignals || [];

    // Weighted positive signals per member
    const weighted = signals.map(s => {
      const daysDiff = Math.floor((today - new Date(s.date)) / (1000*60*60*24));
      let weight;
      if (daysDiff <= 7) weight = "HIGH";
      else if (daysDiff <= 30) weight = "MEDIUM";
      else weight = "LOW";
      return `${s.type} (${daysDiff} days ago, recency: ${weight})`;
    });

    // Parsed negative signals per member
    const parsedNegative = negativeSignals.map(n => {
      const daysDiff = Math.floor((today - new Date(n.date)) / (1000*60*60*24));
      return `${n.type}: ${n.description} (${daysDiff} days ago)`;
    });

    return {
      contactName: member.contactName,
      jobTitle: member.jobTitle,
      weightedSignals: weighted.join(', ') || 'No signals',
      parsedNegativeSignals: parsedNegative.join(' | ') || 'None',
      hasNegativeSignals: negativeSignals.length > 0,
      engaged: signals.length > 0
    };
  });

  // Buying group coverage calculation
  const engagedCount = processedGroup.filter(m => m.engaged).length;
  const totalCount = processedGroup.length;
  const coveragePct = totalCount > 0 ? Math.round((engagedCount / totalCount) * 100) : 0;
  const coverageLabel = coveragePct >= 66 ? "BROAD" : coveragePct >= 33 ? "PARTIAL" : "NARROW";
  const engagedRoles = processedGroup.filter(m => m.engaged).map(m => `${m.contactName} (${m.jobTitle})`).join(', ');

  // Aggregate all negative signals across buying group
  const allNegativeSignals = processedGroup
    .filter(m => m.hasNegativeSignals)
    .map(m => `[${m.contactName}] ${m.parsedNegativeSignals}`)
    .join(' | ');

  const hasAnyNegativeSignals = processedGroup.some(m => m.hasNegativeSignals);

  // Summary of all weighted signals across buying group
  const allWeightedSignals = processedGroup
    .filter(m => m.engaged)
    .map(m => `[${m.contactName} - ${m.jobTitle}] ${m.weightedSignals}`)
    .join(' | ');

  return {
    json: {
      ...item.json,
      buyingGroupProcessed: processedGroup,
      allWeightedSignals,
      allNegativeSignals: allNegativeSignals || 'None',
      hasAnyNegativeSignals,
      buyingGroupCoverage: coveragePct,
      coverageLabel,
      engagedRoles,
      engagedCount,
      totalCount
    }
  };
});

