// Format Adapter
// Handles three schemas:
//   - Jocelyn (WHEN Layer): has meta.engine === "WHEN Layer Intelligence Engine"
//   - Tabita (CaP context): has account_id + context_status
//   - Pipeline native: has company + buyingGroup directly

return $input.all().map(item => {
  const data = item.json;

  if (data.meta && data.meta.engine === "WHEN Layer Intelligence Engine") {
    const accountSignals = data.signals || [];
    const firstSignal = accountSignals[0] || {};

    const buyingGroup = (data.buying_group || []).map(member => {
      const status = (member.status || "").toString().toUpperCase();
      const isConfirmed = status === "COMPLETE" || status === "CONFIRMED";
      return {
        contactName: member.name,
        jobTitle: member.title,
        signals: isConfirmed ? accountSignals.map(s => ({ type: s.type, date: s.date })) : [],
        negativeSignals: []
      };
    });

    const unenriched = (data.buying_group || []).filter(m => {
      const s = (m.status || "").toString().toUpperCase();
      return s !== "COMPLETE" && s !== "CONFIRMED";
    });
    const enrichmentNeeded = unenriched.length > 0;
    const unenrichedRoles = unenriched.map(m => m.name + (m.focus_area ? " (" + m.focus_area + ")" : "")).join(", ");

    return {
      json: {
        company: data.account.name,
        companySize: null,
        triggerEvent: {
          eventType: firstSignal.type || "Structural Trigger",
          description: firstSignal.description || data.posture?.headline || "",
          category: data.account.theme,
          isActionable: data.posture?.urgency !== "MONITOR"
        },
        buyingGroup,
        when_open_with:    data.outreach?.open_with || null,
        when_action:       data.outreach?.action || null,
        when_stage:        data.posture?.gate_3 || data.posture?.stage || null,
        when_urgency:      data.posture?.urgency || null,
        when_window_close: data.change_triggers?.window_close_date || null,
        when_whats_at_stake: (data.whats_at_stake || []).map(w => w.role + ": " + w.statement).join(" | ") || null,
        when_the_move:       data.element_4?.the_move || null,
        when_the_catch:      data.element_4?.the_catch || null,
        when_your_edge:      data.element_4?.your_edge || null,
        when_first_step:     data.element_4?.first_step || null,
        when_campaign_stage: data.outreach?.campaign_stage || null,
        when_belief_shift:   data.outreach?.belief_shift_objective || null,
        posture_detail:    data.posture?.detail || null,
        supporting_signals: data.element_4?.supporting_signals || [],
        signal_sources:    (data.signals || []).filter(s => s.source_url).map(s => ({ label: s.source_label || s.type || "source", url: s.source_url })),
        industry:          data.account?.industry || null,
        theme:             data.account?.theme || null,
        trigger_notes:     data.change_triggers?.notes || null,
        enrichmentNeeded:  enrichmentNeeded,
        unenrichedRoles:   unenrichedRoles,
        _source: "jocelyn",
        _raw: data
      }
    };
  }

  if (data.account_id && data.context_status) {
    const identity     = data.background?.identity || {};
    const facts        = data.background?.structural_facts || [];
    const hypothesis   = data.background?.operational_hypothesis || {};
    const primaryFact  = facts.find(f => f.type === "A") || facts[0] || {};
    const highTensions = (data.tensions || []).filter(t => t.level === "HIGH");
    const type1Gaps    = data.gaps?.type_1 || [];

    let buyingGroup = (data.stakeholder_map?.buying_committee || []).map(member => ({
      contactName: member.name || member.contactName,
      jobTitle:    member.title || member.jobTitle,
      signals:     [],
      negativeSignals: highTensions.map(t => ({ type: "high_tension", date: new Date().toISOString().split("T")[0], description: t.conflict }))
    }));

    if (buyingGroup.length === 0) {
      buyingGroup = [{ contactName: "Unknown - see Type I gaps", jobTitle: type1Gaps.map(g => g.gap).join(" | ") || "TBD", signals: [], negativeSignals: highTensions.map(t => ({ type: "high_tension", date: new Date().toISOString().split("T")[0], description: t.conflict })) }];
    }

    return {
      json: {
        company:     identity.company || data.account_id,
        companySize: null,
        triggerEvent: { eventType: primaryFact.event || "Structural Event", description: hypothesis.statement || primaryFact.event || "", category: identity.industry || "Unknown", isActionable: type1Gaps.length === 0 },
        buyingGroup,
        cap_confidence_floor:    data.confidence_floor,
        cap_primary_archetype:   data.pattern?.primary_archetype || null,
        cap_secondary_archetype: data.pattern?.secondary_archetype || null,
        cap_context_status:      data.context_status,
        cap_type1_gap_count:     type1Gaps.length,
        cap_high_tension_count:  highTensions.length,
        _source: "tabita",
        _raw: data
      }
    };
  }

  return { json: { ...data, _source: "direct", _raw: data } };
});

const crypto = require('crypto');
const SECRET = $('Get HMAC Secret').first().json.value;
function sign(id, action) {
  return crypto.createHmac('sha256', SECRET).update(`brief:${id}:${action}`).digest('hex').slice(0, 32);
}
const item = { ...$('Insert rows in a table').item.json };
const id = item.id;
const base = 'https://designprodigy.app.n8n.cloud/webhook/brief-approval';
item.approveUrl = `${base}?id=${id}&action=approve&sig=${sign(id, 'approve')}`;
item.rejectUrl  = `${base}?id=${id}&action=reject&sig=${sign(id, 'reject')}`;
return [{ json: item }];
